package vn.crossdock;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;
import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import java.util.*;import static vn.crossdock.Db.*;
@Service public class ExcelService {
 final Db db;public ExcelService(Db db){this.db=db;}
 static final List<String> HEAD=List.of("ma_thung","ma_linh_kien","ten_linh_kien","so_luong","trong_luong_kg","ma_yeu_cau","ma_xac_nhan");
 @Transactional public Map<String,Object> importBoxes(long lotId,MultipartFile file,boolean preview)throws Exception{
 db.lock();require(file.getSize()>0&&file.getSize()<=5_000_000,"Tệp rỗng hoặc quá 5 MB");require(Objects.toString(file.getOriginalFilename(),"").toLowerCase().endsWith(".xlsx"),"Chỉ nhận tệp .xlsx");var lot=db.get("lo_nhap",lotId);require("EXPECTED".equals(s(db.get("chuyen_nhap",n(lot,"inbound_id")),"status")),"Chỉ nhập dữ liệu dự kiến trước khi xe vào kho");List<Map<String,Object>> data=new ArrayList<>();List<String> errors=new ArrayList<>();Set<String> seen=new HashSet<>();Map<Long,Long> bySupply=new HashMap<>();
 try(var wb=new XSSFWorkbook(file.getInputStream())){var sh=wb.getSheetAt(0);require(sh.getLastRowNum()<=2000,"Tối đa 2.000 thùng một tệp");require(sh.getRow(0)!=null,"Thiếu tiêu đề");DataFormatter fmt=new DataFormatter(Locale.ROOT);for(int c=0;c<HEAD.size();c++)require(HEAD.get(c).equals(fmt.formatCellValue(sh.getRow(0).getCell(c)).trim()),"Cột "+(c+1)+" phải là "+HEAD.get(c));
 for(int i=1;i<=sh.getLastRowNum();i++){var row=sh.getRow(i);if(row==null)continue;List<String> v=new ArrayList<>();for(int c=0;c<7;c++){Cell cell=row.getCell(c);require(cell==null||cell.getCellType()!=CellType.FORMULA,"Không dùng công thức trong dữ liệu nhập");v.add(fmt.formatCellValue(cell).trim());}if(v.stream().allMatch(String::isBlank))continue;
 try{require(v.get(0).matches("[A-Za-z0-9_-]{1,60}"),"Mã thùng chỉ gồm chữ, số, _ hoặc -");require(seen.add(v.get(0)),"Trùng mã thùng trong tệp");require(db.count("select count(*) from thung_hang where lot_id=? and source_code=?",lotId,v.get(0))==0,"Thùng đã nhập trước đó");var part=db.one("select * from linh_kien where code=? and active",v.get(1));require(s(part,"name").equalsIgnoreCase(v.get(2)),"Tên linh kiện không khớp mã");long qty=Long.parseLong(v.get(3)),supplyId=Long.parseLong(v.get(6));double kg=Double.parseDouble(v.get(4));require(qty>0&&qty<=1000000&&Double.isFinite(kg)&&kg>0&&kg<=18000,"Số lượng/kg không hợp lệ");var r=db.one("select * from yeu_cau_giao where code=? and status='OPEN'",v.get(5));var detail=db.one("select * from chi_tiet_yeu_cau where requirement_id=? and part_id=?",n(r,"id"),n(part,"id"));var supply=db.get("xac_nhan_cung_cap",supplyId);require("ACCEPTED".equals(s(supply,"status"))&&n(supply,"supplier_id")==n(lot,"supplier_id")&&n(supply,"detail_id")==n(detail,"id"),"Xác nhận cung cấp không đúng nhà cung cấp/linh kiện/yêu cầu");long cum=bySupply.getOrDefault(supplyId,0L)+qty;require(cum+db.count("select coalesce(sum(expected_qty),0) from thung_hang where supply_id=?",supplyId)<=n(supply,"quantity"),"Vượt số lượng đã cam kết cung cấp");bySupply.put(supplyId,cum);data.add(Map.of("source_code",v.get(0),"part_id",n(part,"id"),"detail_id",n(detail,"id"),"supply_id",supplyId,"quantity",qty,"kg",kg));}
 catch(Exception e){errors.add("Dòng "+(i+1)+": "+(e instanceof NumberFormatException?"Số lượng/kg/mã xác nhận phải là số hợp lệ":e.getMessage()));}}
 }
 require(!data.isEmpty()||!errors.isEmpty(),"Tệp không có dữ liệu");if(!errors.isEmpty())return Map.of("ok",false,"errors",errors,"count",data.size());
 if(!preview)for(var row:data)db.insert("insert into thung_hang(code,source_code,lot_id,part_id,detail_id,supply_id,expected_qty,gross_kg) values(?,?,?,?,?,?,?,?)",Workflow.code("IN"),row.get("source_code"),lotId,row.get("part_id"),row.get("detail_id"),row.get("supply_id"),row.get("quantity"),row.get("kg"));
 return Map.of("ok",true,"preview",preview,"count",data.size(),"rows",data,"message",preview?"Dữ liệu hợp lệ. Chọn Nhập chính thức để lưu.":"Đã lưu hàng dự kiến; chưa tăng hàng sẵn sàng.");
 }
}
